// The three trunks of the herd, as assets-src/heart/torso.py made them: the coarse surface of each, rings by sides by (forward, up, left),
// in metres of an animal of size 1 times 8192. The fine surface is in mat/trunk.jpg.
export const TRUNK_RINGS = 128;
export const TRUNK_SIDES = 32;
const PACKED: readonly string[] = [
  '',
  '',
  '',
];

export function trunkTable(which: number): Float32Array {
  const text = atob(PACKED[which] as string);
  const out = new Float32Array(text.length / 2);
  for (let i = 0; i < out.length; i++) {
    const v = text.charCodeAt(i * 2) | (text.charCodeAt(i * 2 + 1) << 8);
    out[i] = (v >= 32768 ? v - 65536 : v) / 8192;
  }
  return out;
}
